import React, { useEffect, useState } from "react";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import SearchIcon from "@mui/icons-material/Search";
import { TextField, InputAdornment } from "@mui/material";
import OrderImage from "../../assets/orders/order1.png";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import Select from "@mui/material/Select";
import {
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  Button,
} from "@mui/material";
import { useLocation, useNavigate } from "react-router-dom";
import http from "../../services/utility";
import { apisPath, paths } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";
import { open, setId } from "../../redux/reducer/ProductStockReducer";

export default function ProductList() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { state } = useLocation();
  const [brandId, setBrandId] = useState(state?.brandId);
  const [catId, setCatId] = useState(state?.catId);
  const [subCatId, setSubCatId] = useState(state?.subCatId);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [apiTableData, setApiTableData] = useState([]);

  const [page, setPage] = useState(1);
  const [limit, setLimit] = useState(20);
  const [pagination, setPagination] = useState({
    total: 0,
    currentPage: 1,
    totalPages: 1,
    hasNextPage: false,
    hasPrevPage: false,
  });

  // Dropdown data
  const [brands, setBrands] = useState([]);
  const [categories, setCategories] = useState([]);
  const [subcategories, setSubcategories] = useState([]);

  // Delete modal state
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [productToDelete, setProductToDelete] = useState(null);

  const [tableHeader, setTableHeader] = useState([
    { name: "Product" },
    { name: "Price" },
    { name: "Pack Size / Unit" },
    { name: "Stock" },
    { name: "Expiry date" },
    { name: "Action" },
  ]);
  const [tableData, setTableData] = useState([]);

  // Debounce search
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
    }, 500);

    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    getData();
  }, [page, catId, subCatId, brandId, debouncedSearch]);

  useEffect(() => {
    // Fetch dropdown data on component mount
    fetchBrands();
    fetchCategories();
    fetchSubcategories();
  }, []);

  const fetchBrands = async () => {
    try {
      const res = await http.get(apisPath?.admin?.brands);
      setBrands(res?.data?.brands || []);
    } catch (err) {
      console.log("Error fetching brands:", err);
    }
  };

  const fetchCategories = async () => {
    try {
      const res = await http.get(apisPath?.admin?.allCategories);
      setCategories(res?.data?.categories || []);
    } catch (err) {
      console.log("Error fetching categories:", err);
    }
  };

  const fetchSubcategories = async () => {
    try {
      const res = await http.get(apisPath?.admin?.allSubcategories);
      setSubcategories(res?.data?.subcategories || []);
    } catch (err) {
      console.log("Error fetching subcategories:", err);
    }
  };

  const getData = async () => {
    // Build query params
    let queryParams = `page=${page}&limit=${limit}`;
    if (catId) queryParams += `&catId=${catId}`;
    if (subCatId) queryParams += `&subCatId=${subCatId}`;
    if (brandId) queryParams += `&brandId=${brandId}`;
    if (debouncedSearch) queryParams += `&search=${debouncedSearch}`;

    await http
      .get(`${apisPath?.admin?.allProducts}?${queryParams}`)
      .then(async (res) => {
        console.log("API Response:", res?.data);
        let data = res?.data?.data?.products || [];
        let paginationData = res?.data?.data?.pagination || {};

        let tabledata = [];
        for (let i = 0; i < data.length; i++) {
          tabledata.push({
            id: data[i]?.id,
            image: data[i]?.images?.[0] || OrderImage,
            name: data[i]?.name || "N/A",
            detail: data[i]?.details?.[0]?.body || "No details",
            price: data[i]?.varients?.[0]?.premiumPrice || data[i]?.varients?.[0]?.sellingPrice || "0",
            pack_size: data[i]?.varients?.[0]?.units || "0",
            stock: data[i]?.varients?.[0]?.stock || "0",
            expiry_date: ((dateString) => {
              if (!dateString) return "N/A";
              const date = new Date(dateString);
              if (isNaN(date.getTime())) return "N/A";
              const day = String(date.getDate()).padStart(2, "0");
              const month = String(date.getMonth() + 1).padStart(2, "0");
              const year = date.getFullYear();
              return `${day}-${month}-${year}`;
            })(data[i]?.varients?.[0]?.date),
          });
        }
        setTableData(tabledata);
        setApiTableData(data);
        setPagination(paginationData);
      })
      .catch((err) => {
        console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message || "Failed to fetch products" })
        );
      });
  };

  const openDeleteModal = (product) => {
    setProductToDelete(product);
    setDeleteModalOpen(true);
  };

  const handleCloseDeleteModal = () => {
    setDeleteModalOpen(false);
    setProductToDelete(null);
  };

  const confirmDelete = async () => {
    if (!productToDelete) return;

    await http
      .delete(`${apisPath?.admin?.products}/${productToDelete.id}`)
      .then(async (res) => {
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
        handleCloseDeleteModal();
      })
      .catch((err) => {
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
        handleCloseDeleteModal();
      });
  };

  const stockUpdatePopup = (id) => {
    dispatch(setId({ id: id }));
    dispatch(open());
  };

  return (
    <div className="product_list">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Products List</h3>
      </div>
      <div className="product_list__content">
        <div className="product_list__content__filter" style={{
          display: 'grid',
          gridTemplateColumns: '1.5fr 1fr 1fr 1fr',
          gap: '20px',
          marginBottom: '20px',
          maxWidth: '100%'
        }}>
          {/* Search Bar */}
          <FormControl fullWidth>
            <TextField
              placeholder="Search Products..."
              variant="outlined"
              size="small"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setPage(1);
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
              sx={{
                backgroundColor: 'white',
              }}
            />
          </FormControl>
          {/* Brand Filter */}
          <FormControl fullWidth>
            <Select
              value={brandId || ""}
              onChange={(e) => {
                setBrandId(e.target.value || undefined);
                setPage(1); // Reset to page 1 when filter changes
              }}
              displayEmpty
            >
              <MenuItem value="">All Brands</MenuItem>
              {brands.map((brand) => (
                <MenuItem key={brand.id} value={brand.id}>
                  {brand.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* Category Filter */}
          <FormControl fullWidth>
            <Select
              value={catId || ""}
              onChange={(e) => {
                setCatId(e.target.value || undefined);
                setPage(1); // Reset to page 1 when filter changes
              }}
              displayEmpty
            >
              <MenuItem value="">All Categories</MenuItem>
              {categories.map((category) => (
                <MenuItem key={category.id} value={category.id}>
                  {category.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {/* Subcategory Filter */}
          <FormControl fullWidth>
            <Select
              value={subCatId || ""}
              onChange={(e) => {
                setSubCatId(e.target.value || undefined);
                setPage(1); // Reset to page 1 when filter changes
              }}
              displayEmpty
            >
              <MenuItem value="">All Subcategories</MenuItem>
              {subcategories.map((subcategory) => (
                <MenuItem key={subcategory.id} value={subcategory.id}>
                  {subcategory.name}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </div>
        <div className="product_list__content__table">
          <table className="product_list__content__table__table">
            <tr>
              {tableHeader?.map((header, index) => {
                return (
                  <th key={index}>
                    <span>
                      {header?.name} <ArrowDropDownIcon />
                    </span>
                  </th>
                );
              })}
            </tr>
            {tableData?.map((data, index) => {
              return (
                <tr key={index}>
                  <td>
                    <div className="product div-flex">
                      <img src={data?.image} alt="Product Image" />
                      <div className="product__info">
                        <span>{data?.name}</span>
                      </div>
                    </div>
                  </td>
                  <td>&#8377; {data?.price ? data?.price : "-"}</td>
                  <td>{data?.pack_size ? data?.pack_size : "-"}</td>
                  <td>{data?.stock ? data?.stock : "-"}</td>
                  <td>{data?.expiry_date}</td>
                  <td>
                    <div className="product_action">
                      <button
                        className="button-red"
                        onClick={() => openDeleteModal(apiTableData[index])}
                      >
                        Delete
                      </button>
                      {/* <button
                        className="button-border-red"
                        onClick={() => stockUpdatePopup(data?.id)}
                      >
                        Stock update
                      </button> */}
                      <span
                        onClick={() =>
                          navigate(
                            `/${paths?.front?.user?.products}/${paths?.front?.user?.add_products}`,
                            {
                              state: {
                                data: apiTableData[index],
                                catId: catId,
                                subCatId: subCatId,
                                editProduct: true,
                                brandId: brandId,
                              },
                            }
                          )
                        }
                      >
                        Edit
                      </span>
                    </div>
                  </td>
                </tr>
              );
            })}
          </table>
        </div>

        {/* Pagination Controls */}
        <div className="product_list__pagination" style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '20px',
          marginTop: '20px',
          borderTop: '1px solid #e0e0e0'
        }}>
          <div style={{ fontSize: '14px', color: '#666' }}>
            Showing {tableData.length} of {pagination.total} products
            (Page {pagination.currentPage} of {pagination.totalPages})
          </div>

          <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
            <button
              className="button-border-red"
              onClick={() => setPage(page - 1)}
              disabled={!pagination.hasPrevPage}
              style={{
                opacity: pagination.hasPrevPage ? 1 : 0.5,
                cursor: pagination.hasPrevPage ? 'pointer' : 'not-allowed'
              }}
            >
              Previous
            </button>

            <span style={{ fontSize: '14px', padding: '0 10px' }}>
              Page {pagination.currentPage}
            </span>

            <button
              className="button-red"
              onClick={() => setPage(page + 1)}
              disabled={!pagination.hasNextPage}
              style={{
                opacity: pagination.hasNextPage ? 1 : 0.5,
                cursor: pagination.hasNextPage ? 'pointer' : 'not-allowed'
              }}
            >
              Next
            </button>
          </div>
        </div>
      </div>

      {/* Delete Confirmation Modal */}
      <Dialog
        open={deleteModalOpen}
        onClose={handleCloseDeleteModal}
        aria-labelledby="delete-dialog-title"
        aria-describedby="delete-dialog-description"
        className="product_list__delete_modal"
        disablePortal={false}
        container={document.body}
        style={{
          position: 'fixed',
          zIndex: 9999999,
        }}
        BackdropProps={{
          style: {
            position: 'fixed',
            zIndex: 9999998,
          },
        }}
      >
        <DialogTitle id="delete-dialog-title">Delete Product</DialogTitle>
        <DialogContent>
          <div className="delete-icon-container">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M19 7L18.1327 19.1425C18.0579 20.1891 17.187 21 16.1378 21H7.86224C6.81296 21 5.94208 20.1891 5.86732 19.1425L5 7M10 11V17M14 11V17M15 7V4C15 3.44772 14.5523 3 14 3H10C9.44772 3 9 3.44772 9 4V7M4 7H20" stroke="#dc2626" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </div>
          <DialogContentText id="delete-dialog-description">
            Are you sure you want to delete <strong>"{productToDelete?.name}"</strong>?
          </DialogContentText>
          <DialogContentText>
            This action cannot be undone. All associated data will be permanently removed.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDeleteModal} variant="outlined" className="cancel-btn">
            Cancel
          </Button>
          <Button onClick={confirmDelete} variant="contained" className="delete-btn">
            Delete Product
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}
